      "name": "b8ccdcb0",
      "displayName": "Total policies",
      "queryLines": [
        "SELECT COUNT(*) AS policies FROM __PWCATALOG__.__PWSCHEMA__.unified_pricing_table_live"
      ]
    },
    {
      "name": "b187ee1a",
      "displayName": "Total GWP (£m)",
      "queryLines": [
        "SELECT SUM(current_premium) / 1e6 AS gwp_m FROM __PWCATALOG__.__PWSCHEMA__.unified_pricing_table_live"
      ]
    },
    {
      "name": "dafc5070",
      "displayName": "Total incurred claims 5y (£m)",
      "queryLines": [
        "SELECT SUM(total_incurred_5y) / 1e6 AS claims_m FROM __PWCATALOG__.__PWSCHEMA__.unified_pricing_table_live"
      ]
    },
    {
      "name": "9b571aa1",
      "displayName": "Portfolio 5-yr loss ratio (%)",
      "queryLines": [
        "SELECT ROUND(SUM(total_incurred_5y) * 100.0 / NULLIF(SUM(current_premium), 0), 1) AS loss_ratio_pct FROM __PWCATALOG__.__PWSCHEMA__.unified_pricing_table_live"
      ]
    },
    {
      "name": "e1f90c1f",
      "displayName": "Policies by region",
      "queryLines": [
        "SELECT region, COUNT(*) AS policies FROM __PWCATALOG__.__PWSCHEMA__.unified_pricing_table_live GROUP BY region ORDER BY policies DESC"
      ]
    },
    {
      "name": "67009911",
      "displayName": "GWP by industry tier",
      "queryLines": [
        "SELECT industry_risk_tier AS tier, ROUND(SUM(current_premium) / 1e6, 1) AS gwp_m FROM __PWCATALOG__.__PWSCHEMA__.unified_pricing_table_live GROUP BY industry_risk_tier ORDER BY gwp_m DESC"
      ]
    },
    {
      "name": "c5dbb296",
      "displayName": "Policies by construction",
      "queryLines": [
        "SELECT construction_type, COUNT(*) AS n FROM __PWCATALOG__.__PWSCHEMA__.unified_pricing_table_live GROUP BY construction_type ORDER BY n DESC"
      ]
    },
    {
      "name": "8191a4aa",
      "displayName": "Flood zone distribution",
      "queryLines": [
        "SELECT flood_zone_rating AS zone, COUNT(*) AS n FROM __PWCATALOG__.__PWSCHEMA__.unified_pricing_table_live GROUP BY flood_zone_rating ORDER BY zone"
      ]
    },
    {
      "name": "f629528b",
      "displayName": "Top 15 postcodes by GWP",
      "queryLines": [
        "SELECT postcode_sector,  CAST(COUNT(*) AS INT)                            AS policies,  ROUND(SUM(current_premium) / 1e6, 2)             AS gwp_m,  ROUND(SUM(total_incurred_5y) / 1e6, 2)           AS claims_m_5y FROM __PWCATALOG__.__PWSCHEMA__.unified_pricing_table_live GROUP BY postcode_sector ORDER BY gwp_m DESC LIMIT 15"
      ]
    }
  ],
